// ===== GENERATE PATTERNS FOR API =====

function generatePatterns(length) {
    const patterns = [];
    const letters = 'abcdefghijklmnopqrstuvwxyz';

    // Base pattern: all question marks
    patterns.push('?'.repeat(length));

    // Patterns with fixed first letter (first 10 letters)
    for (let i = 0; i < 10 && i < letters.length; i++) {
        patterns.push(letters[i] + '?'.repeat(length - 1));
    }

    // Patterns with fixed last letter (first 10 letters)
    for (let i = 0; i < 10 && i < letters.length; i++) {
        patterns.push('?'.repeat(length - 1) + letters[i]);
    }

    // For 4-letter words, add more specific patterns
    if (length === 4) {
        // Patterns with fixed first two letters
        for (let i = 0; i < 5 && i < letters.length; i++) {
            for (let j = 0; j < 5 && j < letters.length; j++) {
                patterns.push(letters[i] + letters[j] + '?' + '?');
            }
        }
    }

    return patterns;
}

// ===== LOAD WORDS FROM MULTIPLE SOURCES =====

async function fetchEnglishWords(length) {
    try {
        // Start with built-in dictionary
        let allWords = [...getExtendedEnglishDictionary(length)];
        let apiWords = [];

        // Show loading message
        function updateProgress(message) {
            $('.info').empty();
            $('.info').append(message);
            document.body.offsetHeight; // Force DOM update
        }

        updateProgress("Loading words from API... (0%");

        // Try to get words from API
        const patterns = generatePatterns(length);
        const maxRequests = Math.min(patterns.length, 6); // Limit to 6 requests

        const requests = patterns.slice(0, maxRequests).map(async (pattern, index) => {
            const url = `https://api.datamuse.com/words?sp=${pattern}&max=500`;
            try {
                const response = await fetch(url);
                if (!response.ok) return [];
                const data = await response.json();
                const words = data.map(item => item.word);

                // Update progress
                const progress = Math.round(((index + 1) / maxRequests) * 100);
                updateProgress("Loading words from API... (" + progress + "%)");

                return words;
            } catch (error) {
                console.warn('Error fetching pattern:', pattern, error);
                return [];
            }
        });

        // Wait for all API requests
        const results = await Promise.all(requests);

        // Combine API results
        for (const words of results) {
            apiWords = apiWords.concat(words);
        }

        // Filter API words
        const filteredApiWords = apiWords.filter(word =>
            word.length === length &&
            new Set(word).size === length &&
            /^[a-z]+$/.test(word) &&
            !word.includes(' ') &&
            !word.includes('-') &&
            !word.includes("'") &&
            word === word.toLowerCase()
        );

        // Remove duplicates from API words
        const uniqueApiWords = [...new Set(filteredApiWords)];

        // Combine built-in dictionary with API words (no duplicates)
        const combined = [...allWords, ...uniqueApiWords];
        const finalWords = [...new Set(combined)];

        console.log('Built-in dictionary size:', allWords.length);
        console.log('API words found:', uniqueApiWords.length);
        console.log('Final dictionary size:', finalWords.length);

        // If we have very few words, use extended dictionary
        if (finalWords.length < 20) {
            console.log('Too few words, using extended dictionary');
            return getExtendedEnglishDictionary(length);
        }

        return finalWords;
    } catch (error) {
        console.warn('Error loading words, using extended dictionary:', error);
        return getExtendedEnglishDictionary(length);
    }
}

// ===== UI CREATION FUNCTIONS =====

function createInputField(n, sizeField) {
    let inputField = document.createElement("div");
    inputField.className = "inputField";

    let inputForm = document.createElement("form");
    inputForm.name = 'inputWord';
    inputForm.className = 'inputWord';
    inputForm.autocomplete = 'off';

    let i = 0;
    while (i < n) {
        let inputLetter = document.createElement("input");
        inputLetter.name = "let" + i;
        inputLetter.type = 'text';
        inputLetter.maxLength = "1";
        inputLetter.className = "inputLetter";
        inputLetter.placeholder = "?";
        inputLetter.autocomplete = 'off';
        inputForm.append(inputLetter);
        i += 1;
    }
    inputField.append(inputForm);

    let info = document.createElement("div");
    info.className = "info";
    info.append("Enter your word");
    inputField.append(info);

    let buttonGroup = document.createElement("div");
    buttonGroup.className = "button-group";

    let checkBut = document.createElement("input");
    checkBut.type = "button";
    checkBut.name = "check";
    checkBut.value = "Check";
    checkBut.className = "check";
    buttonGroup.append(checkBut);

    let giveUp = document.createElement("input");
    giveUp.type = "button";
    giveUp.name = "giveUp";
    giveUp.value = "Give up";
    giveUp.className = "giveUp";
    buttonGroup.append(giveUp);

    inputField.append(buttonGroup);

    $('.game-container').prepend(inputField);
}

function createHistory() {
    let history = document.createElement("div");
    history.className = 'history';

    // Создаем таблицу с заголовками
    let table = document.createElement("table");
    let thead = document.createElement("thead");
    let headerRow = document.createElement("tr");

    let wordTh = document.createElement("th");
    wordTh.textContent = "Word";
    headerRow.append(wordTh);

    let bullsTh = document.createElement("th");
    bullsTh.textContent = "Bulls";
    headerRow.append(bullsTh);

    let cowsTh = document.createElement("th");
    cowsTh.textContent = "Cows";
    headerRow.append(cowsTh);

    thead.append(headerRow);
    table.append(thead);

    let tbody = document.createElement("tbody");
    tbody.id = "historyBody";
    table.append(tbody);

    history.append(table);
    $('.game-container').append(history);
}

function addHistoryEntry(inputWord, bulls, cows) {
    let tbody = document.getElementById('historyBody');
    if (!tbody) {
        // Если tbody не найден, создаем заново
        createHistory();
        tbody = document.getElementById('historyBody');
    }

    let row = document.createElement("tr");

    let wordTd = document.createElement("td");
    wordTd.textContent = inputWord;
    wordTd.className = "word-cell";
    row.append(wordTd);

    let bullsTd = document.createElement("td");
    bullsTd.textContent = bulls;
    bullsTd.className = "bulls-cell";
    row.append(bullsTd);

    let cowsTd = document.createElement("td");
    cowsTd.textContent = cows;
    cowsTd.className = "cows-cell";
    row.append(cowsTd);

    tbody.append(row);

    // Прокручиваем историю вниз
    let historyContainer = document.querySelector('.history');
    if (historyContainer) {
        historyContainer.scrollTop = historyContainer.scrollHeight;
    }
}

// ===== MAIN GAME LOGIC =====

$(document).ready(async function() {
    // Get parameters from URL
    const urlParams = new URLSearchParams(window.location.search);
    let n = parseInt(urlParams.get('length'));
    let lang = urlParams.get('lang');

    // Check if parameters exist
    if (!n || !lang) {
        alert('Please select game settings on the main page first!');
        window.location.href = 'index.html';
        return;
    }

    // Validate parameters
    if (n !== 4 && n !== 5) {
        alert('Invalid word length. Please choose 4 or 5 letters.');
        window.location.href = 'index.html';
        return;
    }

    if (lang !== 'rus' && lang !== 'eng') {
        alert('Invalid language selection. Please choose Russian or English.');
        window.location.href = 'index.html';
        return;
    }

    let sizeField = 400;

    createInputField(n, sizeField);
    createHistory();

    let countColumn = 0;
    let countRow = 0;
    let dictWords = [];

    // Load words based on language
    if (lang == "rus") {
        let rusDict = importRusWords();
        dictWords = rusDict[n] || [];
        $('.info').empty();
        $('.info').append("Введите слово из " + n + " букв");
    } else {
        // Show loading message
        $('.info').empty();
        $('.info').append("Loading words... Please wait.");

        try {
            dictWords = await fetchEnglishWords(n);
        } catch (error) {
            console.error('Error loading words:', error);
            dictWords = getExtendedEnglishDictionary(n);
        }

        // Make sure we have words
        if (dictWords.length < 10) {
            dictWords = getExtendedEnglishDictionary(n);
        }

        // Update info message with word count
        $('.info').empty();
        $('.info').append("Enter a " + n + "-letter word (" + dictWords.length + " words available)");
    }

    // Check if dictionary has words
    if (dictWords.length === 0) {
        alert('No words found for the selected language. Please try different settings.');
        window.location.href = 'index.html';
        return;
    }

    // Select random word
    let randomIndex = randomInteger(0, dictWords.length);
    let word = dictWords[randomIndex];
    console.log('Secret word:', word);
    console.log('Dictionary size:', dictWords.length);

    // Get all input fields
    const inputFields = $(".inputLetter");
    const totalFields = inputFields.length;

    // ==== KEYBOARD NAVIGATION ====

    // 1. ENTER key -> submit the word
    inputFields.keydown(function(e) {
        if (e.key === 'Enter') {
            e.preventDefault(); // Prevent form submission
            $('.check').click(); // Trigger check button
        }
    });

    // 2. BACKSPACE key -> go to previous field if current is empty
    inputFields.keydown(function(e) {
        if (e.key === 'Backspace') {
            const currentField = $(this);
            const currentIndex = inputFields.index(this);

            // If current field is empty and it's not the first field
            if (currentField.val() === '' && currentIndex > 0) {
                e.preventDefault(); // Prevent default backspace behavior
                const prevField = inputFields.eq(currentIndex - 1);
                prevField.focus();
                prevField.val(''); // Clear the previous field as well (optional)
            }
        }
    });

    // 3. Auto-advance to next field when typing
    inputFields.keyup(function() {
        if (this.value.length === this.maxLength) {
            const currentIndex = inputFields.index(this);
            if (currentIndex < totalFields - 1) {
                inputFields.eq(currentIndex + 1).focus();
            }
        }
    });

    // 4. Optional: Click on any field to focus
    inputFields.click(function() {
        this.select();
    });

    // ==== CHECK BUTTON HANDLER ====

    $('.check').click(function() {
        let inputWord = "";
        let form = document.forms.inputWord;

        for (let i = 0; i < n; i++) {
            inputWord += form.elements[i].value;
        }

        // Clear all fields after reading
        for (let i = 0; i < n; i++) {
            form.elements[i].value = '';
        }

        inputWord = inputWord.toLowerCase();

        // Validate input
        if (inputWord.length !== n) {
            $('.info').empty();
            if (lang == "rus") {
                $('.info').append("Введите все " + n + " букв");
            } else {
                $('.info').append("Please enter all " + n + " letters");
            }
            // Focus back on first empty field
            for (let i = 0; i < n; i++) {
                if (form.elements[i].value === '') {
                    form.elements[i].focus();
                    break;
                }
            }
            return;
        }

        if (new Set(inputWord).size != n) {
            $('.info').empty();
            if (lang == "rus") {
                $('.info').append("Все буквы должны быть разными");
            } else {
                $('.info').append("All letters must be unique");
            }
            // Focus back on first field
            form.elements[0].focus();
            return;
        }

        if (!(dictWords.includes(inputWord))) {
            $('.info').empty();
            if (lang == "rus") {
                $('.info').append("Слово не найдено в словаре");
            } else {
                $('.info').append("Word not in dictionary");
            }
            // Focus back on first field
            form.elements[0].focus();
            return;
        }

        // Calculate bulls and cows
        let cows = 0;
        let bulls = 0;
        for (let i = 0; i < n; i++) {
            if (word[i] == inputWord[i]) {
                bulls++;
            } else if (word.includes(inputWord[i])) {
                cows++;
            }
        }

        // Update info message
        $('.info').empty();
        if (bulls != n) {
            if (lang == "rus") {
                $('.info').append("Найдено " + bulls + " быков и " + cows + " коров.");
            } else {
                $('.info').append("Found " + bulls + " bulls and " + cows + " cows.");
            }
        } else {
            if (lang == "rus") {
                $('.info').append("Поздравляем! Вы победили!");
            } else {
                $('.info').append("Hooray! You win!");
            }
        }

        // Добавляем запись в историю (вместо createColumn)
        addHistoryEntry(inputWord, bulls, cows);

        // Focus back on first field for next guess
        form.elements[0].focus();
    });

    // ==== GIVE UP BUTTON HANDLER ====

    $('.giveUp').click(function() {
        let losePhrase = document.createElement("h1");
        losePhrase.className = "losePhrase";
        if (lang == "rus") {
            losePhrase.append("Вы проиграли! Слово было: " + word);
        } else {
            losePhrase.append("You lose! The word was: " + word);
        }
        $('.inputField').empty();
        $('.inputField').append(losePhrase);
    });

    // ==== INITIAL FOCUS ====

    // Focus on first input field when page loads
    inputFields.first().focus();
});